// ---------------------------------------------------------------------------
// Site favicons (fetched from each engine's own website, embedded as
// image/x-icon data URIs). DuckDuckGo's domains are unreachable from some
// networks, so ddg / ddg-lite use a brand-color SVG below instead.
// ---------------------------------------------------------------------------
const SITE_FAVICONS = {
    bing: "data:image/x-icon;base64,",
    anysearch: "data:image/x-icon;base64,",
    keenable: "data:image/x-icon;base64,",
};
// ---------------------------------------------------------------------------
// Browser-session platform icons (小红书 / X) in the 平台搜索源 section.
// xiaohongshu.com favicon fetched from the site; x.com / twimg are unreachable
// from some networks, so X uses its official logo path on black.
// ---------------------------------------------------------------------------
const XHS_FAVICON = "data:image/x-icon;base64,";
/** Official X logo path (24×24). */
const X_LOGO = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><rect width="24" height="24" rx="5" fill="#000"/><path d="M17.21 4.5h2.19l-4.79 5.48 5.64 7.46h-4.42l-3.46-4.53-3.96 4.53H6.22l5.12-5.86L5.94 4.5h4.53l3.13 4.14L17.21 4.5zm-.77 12.02h1.21L8.72 5.67H7.42l9.02 10.85z" fill="#fff"/></svg>`;
/** Icons for the two browser-session platform rows (小红书 / X). */
export const BROWSER_PLATFORM_ICONS = {
    xiaohongshu: XHS_FAVICON,
    x: svgDataUri(X_LOGO),
};
// ---------------------------------------------------------------------------
// platform_search platform favicons — fetched from each site where reachable
// (github / bilibili / reddit / stackoverflow); v2ex / Hacker News / Wikipedia /
// npm are unreachable from some networks, so they use brand-palette marks.
// ---------------------------------------------------------------------------
const PLATFORM_FAVICONS = {
    github: "data:image/x-icon;base64,",
    bilibili: "data:image/x-icon;base64,",
    reddit: "data:image/png;base64,",
    stackoverflow: "data:image/x-icon;base64,",
};
function chipSvg(bg, letter) {
    return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><rect width="24" height="24" rx="6" fill="${bg}"/><text x="12" y="16.5" text-anchor="middle" font-family="system-ui" font-weight="700" font-size="12" fill="#fff">${letter}</text></svg>`;
}
/** Hacker News: the real mark is a white "Y" on #ff6600. */
const HN_LOGO = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><rect width="24" height="24" rx="4" fill="#ff6600"/><path d="M6 6.2l5.1 8.2v5.4h1.8v-5.4L18 6.2h-2l-3.9 6.5L8 6.2H6z" fill="#fff"/></svg>`;
/** npm: the real mark is white "npm" on #CB3838. */
const NPM_LOGO = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><rect width="24" height="24" rx="4" fill="#CB3838"/><path d="M5 9h14v7h-4.6v1.5h-2.4V16H8.2v-1.4H5V9zm2.4 1.5v2.7h2.4V9.5H7.4zm4.2 0v5.6h2.2v-4.2h1.4v4.2h1.6v-5.6h-5.2z" fill="#fff" transform="scale(.9) translate(1.3 1.2)"/></svg>`;
const PLATFORM_META = {
    github: { bg: "#24292F", letter: "G", label: "GitHub", domain: "github.com" },
    v2ex: { bg: "#2F2F2F", letter: "V", label: "V2EX", domain: "v2ex.com" },
    bilibili: { bg: "#FB7299", letter: "B", label: "Bilibili", domain: "bilibili.com" },
    reddit: { bg: "#FF4500", letter: "R", label: "Reddit", domain: "reddit.com" },
    hn: { bg: "#FF6600", letter: "Y", label: "Hacker News", domain: "news.ycombinator.com" },
    stackoverflow: { bg: "#F48024", letter: "S", label: "Stack Overflow", domain: "stackoverflow.com" },
    wikipedia: { bg: "#C8CCD1", letter: "W", label: "Wikipedia", domain: "wikipedia.org" },
    npm: { bg: "#CB3838", letter: "n", label: "npm", domain: "npmjs.com" },
};
export const PLATFORM_BRAND = {};
for (const [name, meta] of Object.entries(PLATFORM_META)) {
    const icon = PLATFORM_FAVICONS[name] ??
        (name === "hn" ? svgDataUri(HN_LOGO)
            : name === "npm" ? svgDataUri(NPM_LOGO)
                : svgDataUri(chipSvg(meta.bg, meta.letter)));
    PLATFORM_BRAND[name] = { icon, label: meta.label, domain: meta.domain };
}
// DuckDuckGo brand mark (official palette): orange disc + white duck "D".
const DDG_LOGO = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><circle cx="12" cy="12" r="12" fill="#DE5833"/><path d="M9 6.6h3.1c2.5 0 4.2 2.1 4.2 5.4s-1.7 5.4-4.2 5.4H9V6.6zm2.1 1.9v7h1c1.4 0 2.2-1.3 2.2-3.5s-.8-3.5-2.2-3.5h-1z" fill="#fff"/></svg>`;
// ---------------------------------------------------------------------------
// Colored-letter fallback for providers without a real logo.
// ---------------------------------------------------------------------------
const FALLBACK_COLORS = {
    exa: { bg: "#1A1A2E", letter: "E", label: "Exa" },
    tavily: { bg: "#4A6CF7", letter: "T", label: "Tavily" },
    brave: { bg: "#FB542B", letter: "B", label: "Brave" },
    you: { bg: "#06B6D4", letter: "Y", label: "You.com" },
    firecrawl: { bg: "#F97316", letter: "F", label: "Firecrawl" },
    parallel: { bg: "#8B5CF6", letter: "P", label: "Parallel" },
    jina: { bg: "#10B981", letter: "J", label: "Jina" },
    searxng: { bg: "#6B7280", letter: "S", label: "SearXNG" },
    bing: { bg: "#008373", letter: "B", label: "Bing" },
    ddg: { bg: "#DE5833", letter: "D", label: "DuckDuckGo" },
    "ddg-lite": { bg: "#E8714F", letter: "D", label: "DuckDuckGo Lite" },
    anysearch: { bg: "#111827", letter: "A", label: "AnySearch" },
    keenable: { bg: "#0EA5E9", letter: "K", label: "Keenable" },
};
function makeFallbackSvg(bg, letter) {
    return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none"><rect width="24" height="24" rx="6" fill="${bg}"/><text x="12" y="16" text-anchor="middle" font-family="system-ui" font-weight="700" font-size="13" fill="#fff">${letter}</text></svg>`;
}
export const PROVIDER_BRAND = {};
for (const [name, meta] of Object.entries(FALLBACK_COLORS)) {
    const icon = SITE_FAVICONS[name] ?? (LOGOS[name] ? svgDataUri(LOGOS[name]) : undefined);
    if (icon) {
        PROVIDER_BRAND[name] = { icon, label: meta.label };
    }
    else {
        PROVIDER_BRAND[name] = { icon: svgDataUri(makeFallbackSvg(meta.bg, meta.letter)), label: meta.label };
    }
}
// DuckDuckGo / DuckDuckGo Lite share the brand mark (site unreachable for a
// favicon fetch, so this is drawn from the official palette instead).
PROVIDER_BRAND["ddg"] = { icon: svgDataUri(DDG_LOGO), label: "DuckDuckGo" };
PROVIDER_BRAND["ddg-lite"] = { icon: svgDataUri(DDG_LOGO), label: "DuckDuckGo Lite" };
